"""Generate the optional MySQL seed from the canonical curriculum JSON."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def sql_string(value):
    # Doubling quotes works with and without MySQL NO_BACKSLASH_ESCAPES.
    # Hex literals avoid depending on that SQL mode when a backslash occurs.
    if "\\" in value:
        return "CONVERT(X'" + value.encode("utf-8").hex() + "' USING utf8mb4)"
    return "'" + value.replace("'", "''") + "'"


def generate(content):
    lines = [
        "-- Generated by python scripts/sync_seed.py; edit docs/data/study_content.json instead.",
        "-- Existing custom rows are retained. Rich learning fields remain in the JSON dataset.",
        "SET NAMES utf8mb4;",
        "USE az4caf_study;",
        "START TRANSACTION;",
        "",
    ]
    for unit in content["units"]:
        lines += [
            "INSERT INTO units (name, semester) VALUES "
            f"({sql_string(unit['name'])}, {int(unit['semester'])})",
            "ON DUPLICATE KEY UPDATE semester=VALUES(semester);",
        ]
    for collection, table, fields in [
        ("notes", "study_notes", ("topic", "category", "vendor", "content", "source_title", "source_url", "case_study")),
        ("flashcards", "flashcards", ("category", "question", "answer")),
    ]:
        for row in content[collection]:
            lines += [
                "",
                f"INSERT INTO {table} (unit_id, {', '.join(fields)})",
                "SELECT id, " + ", ".join(sql_string(row[field]) for field in fields),
                "FROM units WHERE name=" + sql_string(row["unit"]),
                "ON DUPLICATE KEY UPDATE " + ", ".join(f"{field}=VALUES({field})" for field in fields) + ";",
            ]
    lines += ["", "COMMIT;", ""]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if db/seed.sql is stale")
    args = parser.parse_args()
    content = json.loads((ROOT / "docs/data/study_content.json").read_text(encoding="utf-8"))
    seed = ROOT / "db/seed.sql"
    generated = generate(content)
    if args.check:
        if seed.read_text(encoding="utf-8") != generated:
            parser.exit(1, "db/seed.sql is stale; run python scripts/sync_seed.py\n")
        print("MySQL seed matches the curriculum JSON.")
    else:
        seed.write_text(generated, encoding="utf-8")
        print("Updated db/seed.sql")


if __name__ == "__main__":
    main()
